import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int atFlag = 0;
        StringBuilder output = new StringBuilder();

        for (int index = 0; index < inputStr.length(); index++) {
            if (index == 0) {
                output.append(inputStr.charAt(index));
            } else if (index + 2 < inputStr.length() && inputStr.charAt(index) == 'd' && inputStr.charAt(index + 1) == 'o' && inputStr.charAt(index + 2) == 't') {
                if (index + 2 != inputStr.length() - 1) {
                    output.append('.');
                    index += 2;
                } else {
                    output.append(inputStr.charAt(index));
                }
            } else if (atFlag == 0 && index + 1 < inputStr.length() && inputStr.charAt(index) == 'a' && inputStr.charAt(index + 1) == 't') {
                if (index + 1 != inputStr.length() - 1) {
                    output.append('@');
                    atFlag++;
                    index++;
                } else {
                    output.append(inputStr.charAt(index));
                }
            } else {
                output.append(inputStr.charAt(index));
            }
        }
        System.out.println(output.toString());
        scanner.close();
    }
}
